import { transformAsync } from '@babel/core';

/**
 * Preserve the ES5 syntax contract of the historical UMD browser bundles.
 *
 * Babel runs on modules before Rolldown creates the UMD wrapper. This keeps
 * Babel helpers inside the bundle factory and lets Vite run Terser afterwards.
 * A small final pass handles ES2015 syntax generated by Vite/Rolldown itself.
 */
export function legacyUmdPlugin({ enabled = true, compact = true, sourceMaps = false } = {}) {
  return {
    name: 'cherry-legacy-umd',
    async transform(code, id) {
      if (!enabled || !/\.[cm]?js(?:\?|$)/.test(id)) {
        return null;
      }
      const transformed = await transformAsync(code, {
        babelrc: false,
        configFile: false,
        comments: false,
        filename: id.split('?')[0],
        sourceMaps: true,
        presets: [
          [
            '@babel/preset-env',
            {
              bugfixes: true,
              modules: false,
              targets: { ie: '11' },
            },
          ],
        ],
      });

      return transformed?.code ? { code: transformed.code, map: transformed.map } : null;
    },
    generateBundle: {
      order: 'post',
      async handler(outputOptions, bundle) {
        if (!enabled || outputOptions.format !== 'umd') {
          return;
        }

        for (const output of Object.values(bundle)) {
          if (output.type !== 'chunk') {
            continue;
          }

          const transformed = await transformAsync(output.code, {
            babelrc: false,
            configFile: false,
            comments: false,
            compact,
            inputSourceMap: sourceMaps ? output.map || undefined : undefined,
            sourceMaps,
            plugins: [
              '@babel/plugin-transform-arrow-functions',
              '@babel/plugin-transform-shorthand-properties',
              '@babel/plugin-transform-template-literals',
            ],
          });

          if (transformed?.code) {
            output.code = sourceMaps
              ? `${transformed.code}\n//# sourceMappingURL=${output.fileName}.map`
              : transformed.code;
            output.map = sourceMaps ? transformed.map : null;
          }
        }
      },
    },
  };
}
